\node at (2.5,5.6) {Exam distribution};
\end{tikzpicture}
[/tikz]
Find the first quartile ($Q_1$), the third quartile ($Q_3$), and calculate the interquartile range ($IQR$).

The cumulative frequency histogram shows the number of correct answers in a test for $40$ students.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, scale=0.8]
\draw[->] (0,0) -- (0,9.0);
\draw[->] (0,0) -- (6.5,0);
\foreach \y in {10,20,30,40} {\draw (-0.15,\y/5) -- (0,\y/5); \node[left,font=\scriptsize] at (-0.15,\y/5) {$\y$};}
\node[left,font=\scriptsize] at (-0.15,0) {$0$};
\draw (0.5,0) rectangle (1.5,0.8);
\draw (1.5,0) rectangle (2.5,2.4);
\draw (2.5,0) rectangle (3.5,5.2);
\draw (3.5,0) rectangle (4.5,7.0);
\draw (4.5,0) rectangle (5.5,8.0);
\draw[thick] (0.5,0) -- (1.5,0.8) -- (2.5,2.4) -- (3.5,5.2) -- (4.5,7.0) -- (5.5,8.0);
